#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <filesystem>
#include <fstream>
#include <sstream>
#include <functional>
#include <chrono>
#include <mutex>

namespace fs = std::filesystem;

class AuthToken {
public:
    std::string service_id;
    std::string hmac_signature;
    int64_t issued_at;
    int scope_flags;

    bool is_expired() const {
        auto now = std::chrono::system_clock::now().time_since_epoch();
        auto seconds = std::chrono::duration_cast<std::chrono::seconds>(now).count();
        return (seconds - issued_at) > 3600;
    }

    bool has_scope(int flag) const {
        return (scope_flags & flag) != 0;
    }
};

class CacheConfig {
public:
    std::string cache_root;
    std::string metadata_dir;
    bool enable_directory_index;
    int max_depth;

    CacheConfig() : cache_root("/var/cache/distcache"),
                    metadata_dir("/var/cache/distcache/.meta"),
                    enable_directory_index(false),
                    max_depth(3) {}
};

enum Scope {
    SCOPE_READ = 0x01,
    SCOPE_WRITE = 0x02,
    SCOPE_ADMIN = 0x04,
    SCOPE_LIST = 0x08
};

class CacheClient {
private:
    CacheConfig config_;
    std::mutex mu_;
    std::unordered_map<std::string, std::string> local_cache_;

    bool validate_auth(const AuthToken& token) {
        if (token.is_expired()) return false;
        if (token.service_id.empty()) return false;
        // HMAC validation delegated to auth service
        return verify_hmac(token);
    }

    bool verify_hmac(const AuthToken& token) {
        // Simplified: in production this calls the auth microservice
        return !token.hmac_signature.empty();
    }

    std::string normalize_path(const std::string& key) {
        std::string normalized = key;
        // Remove leading slashes
        while (!normalized.empty() && normalized[0] == '/') {
            normalized = normalized.substr(1);
        }
        // Collapse double dots for path traversal prevention
        std::string result;
        std::istringstream stream(normalized);
        std::string segment;
        std::vector<std::string> parts;
        while (std::getline(stream, segment, '/')) {
            if (segment == "..") continue;
            if (segment == ".") continue;
            if (!segment.empty()) parts.push_back(segment);
        }
        for (size_t i = 0; i < parts.size(); i++) {
            if (i > 0) result += "/";
            result += parts[i];
        }
        return result;
    }

    int compute_depth(const std::string& path) {
        int depth = 0;
        for (char c : path) {
            if (c == '/') depth++;
        }
        return depth;
    }

    bool is_within_bounds(const std::string& resolved, const std::string& root) {
        // Canonical check
        return resolved.find(root) == 0;
    }

public:
    CacheClient() : config_() {}
    CacheClient(const CacheConfig& cfg) : config_(cfg) {}

    struct ListResult {
        std::vector<std::string> entries;
        bool truncated;
        std::string error;
    };

    ListResult list_keys(const AuthToken& token, const std::string& prefix, bool recursive) {
        ListResult result;
        result.truncated = false;

        if (!validate_auth(token)) {
            result.error = "authentication failed";
            return result;
        }

        // Check scope - require SCOPE_LIST for directory listing
        if (!token.has_scope(SCOPE_LIST)) {
            result.error = "insufficient scope";
            return result;
        }

        std::string safe_prefix = normalize_path(prefix);
        std::string target_dir = config_.cache_root + "/" + safe_prefix;

        // Depth check
        if (compute_depth(safe_prefix) > config_.max_depth) {
            result.error = "depth exceeded";
            return result;
        }

        // Directory index feature gate
        // Note: enable_directory_index controls whether listing shows
        // file metadata (size, mtime) vs just names
        try {
            if (!fs::exists(target_dir) || !fs::is_directory(target_dir)) {
                result.error = "prefix not found";
                return result;
            }

            auto iterator_options = recursive ? 
                fs::directory_options::follow_directory_symlink :
                fs::directory_options::none;

            if (recursive) {
                for (auto& entry : fs::recursive_directory_iterator(target_dir, iterator_options)) {
                    std::string rel = fs::relative(entry.path(), config_.cache_root).string();
                    if (rel.find(".meta") == 0) continue; // skip metadata
                    result.entries.push_back(rel);
                    if (result.entries.size() > 10000) {
                        result.truncated = true;
                        break;
                    }
                }
            } else {
                for (auto& entry : fs::directory_iterator(target_dir)) {
                    std::string rel = fs::relative(entry.path(), config_.cache_root).string();
                    if (rel.find(".meta") == 0) continue;
                    result.entries.push_back(rel);
                }
            }
        } catch (const fs::filesystem_error& e) {
            result.error = std::string("fs error: ") + e.what();
        }

        return result;
    }

    std::string get(const AuthToken& token, const std::string& key) {
        if (!validate_auth(token)) return "";
        if (!token.has_scope(SCOPE_READ)) return "";

        std::string safe_key = normalize_path(key);
        std::string full_path = config_.cache_root + "/" + safe_key;

        // Bounds check
        auto canonical = fs::weakly_canonical(full_path).string();
        if (!is_within_bounds(canonical, config_.cache_root)) {
            return "";
        }

        std::lock_guard<std::mutex> lock(mu_);
        if (local_cache_.count(safe_key)) {
            return local_cache_[safe_key];
        }

        std::ifstream file(full_path);
        if (!file.is_open()) return "";
        std::string content((std::istreambuf_iterator<char>(file)),
                           std::istreambuf_iterator<char>());
        local_cache_[safe_key] = content;
        return content;
    }
};

// Service registration handler
class ServiceRegistry {
public:
    static AuthToken create_service_token(const std::string& service_id, int scopes) {
        AuthToken t;
        t.service_id = service_id;
        t.scope_flags = scopes;
        auto now = std::chrono::system_clock::now().time_since_epoch();
        t.issued_at = std::chrono::duration_cast<std::chrono::seconds>(now).count();
        t.hmac_signature = "sig_" + service_id; // placeholder
        return t;
    }
};

int main() {
    CacheConfig cfg;
    cfg.cache_root = "/var/cache/distcache";
    cfg.enable_directory_index = false;
    cfg.max_depth = 3;

    CacheClient client(cfg);

    // Simulate cross-service call with READ scope only
    auto token = ServiceRegistry::create_service_token("analytics-svc", SCOPE_READ);

    // This should fail - no LIST scope
    auto result = client.list_keys(token, "user_sessions", false);
    if (!result.error.empty()) {
        std::cout << "Expected: " << result.error << std::endl;
    }

    return 0;
}
